function JournalCard({ journal, saved, onSave }: { journal: Journal; saved: boolean; onSave: (id: string) => void }) {
  return <article className="ji-card group relative border p-5 transition">
    <div className="flex items-start justify-between gap-4"><Link href={`/journals/${journal.id}`} className="min-w-0" data-testid={`link-journal-${journal.id}`}><div className="mono ji-orange text-[10px] uppercase tracking-wider">{journal.abbreviation} · {journal.issn}</div><h3 className="ji-heading mt-2 text-[16px] font-semibold leading-6 group-hover:ji-link">{journal.title}</h3></Link><button onClick={() => onSave(journal.id)} aria-label={saved ? `Remove ${journal.title} from saved` : `Save ${journal.title}`} className={`shrink-0 rounded-sm border p-2 transition ${saved ? 'status-orange border-[#f3c5a8]' : 'border-[#dfe5ee] ji-muted hover:border-[#8faee6] hover:ji-link'}`} data-testid={`button-save-${journal.id}`}><Heart size={15} fill={saved ? 'currentColor' : 'none'} /></button></div>
    <p className="ji-muted mt-3 line-clamp-2 text-[13px] leading-5">{journal.description}</p>
    <div className="mt-4 flex flex-wrap gap-1.5"><Pill tone={journal.quartile === 'Q1' ? 'blue' : 'neutral'}>{journal.quartile}</Pill>{journal.openAccess && <Pill tone="green">Open access</Pill>}{journal.subjects.slice(0, 1).map(subject => <Pill key={subject}>{subject}</Pill>)}</div>
    <div className="mt-5 grid grid-cols-4 border-t border-[#e7edf5] pt-4">{[['SJR', journal.sjr], ['Impact', journal.impact], ['H-index', String(journal.hIndex)], ['Country', journal.country]].map(([label, value]) => <div key={label} className="min-w-0 border-r border-[#e7edf5] pl-2 first:pl-0 last:border-0"><div className="mono ji-muted truncate text-[9px] uppercase tracking-wider">{label}</div><div className="ji-heading mt-1 truncate text-[12px] font-semibold">{value}</div></div>)}</div>
  </article>;
}

function Directory({ saved, onSave }: { saved: string[]; onSave: (id: string) => void }) {
  const [location, setLocation] = useLocation();
  const params = new URLSearchParams(location.split('?')[1] || '');
  const [query, setQuery] = useState(params.get('q') || '');
  const [subject, setSubject] = useState('All subjects');
  const [country, setCountry] = useState('All countries');
  const [quartile, setQuartile] = useState('All quartiles');
  const [savedOnly, setSavedOnly] = useState(params.get('saved') === 'true');
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [sortHigh, setSortHigh] = useState(true);
  const filtered = useMemo(() => journals.filter(j => {
    const hay = `${j.title} ${j.abbreviation} ${j.issn} ${j.publisher} ${j.subjects.join(' ')}`.toLowerCase();
    return (!query || hay.includes(query.toLowerCase())) && (subject === 'All subjects' || j.subjects.includes(subject)) && (country === 'All countries' || j.country === country) && (quartile === 'All quartiles' || j.quartile === quartile) && (!savedOnly || saved.includes(j.id));
  }), [query, subject, country, quartile, savedOnly, saved]);
  const visible = useMemo(() => [...filtered].sort((a, b) => sortHigh ? Number(b.sjr) - Number(a.sjr) : a.title.localeCompare(b.title)), [filtered, sortHigh]);
  const search = (value: string) => { setQuery(value); setLocation(`/journals${value ? `?q=${encodeURIComponent(value)}` : ''}`); };
  const clearFilters = () => { setSubject('All subjects'); setCountry('All countries'); setQuartile('All quartiles'); setSavedOnly(false); };
  return <Shell savedCount={saved.length}><main className="mx-auto max-w-[1240px] px-5 pb-20 pt-10 lg:px-8 lg:pt-14">
    <div className="fade-up"><div className="ji-kicker mono text-[10px] uppercase tracking-[.18em]">Journal directory</div><div className="mt-3 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><h1 className="ji-heading text-4xl font-semibold tracking-[-.04em] sm:text-5xl">Explore indexed journals</h1><p className="ji-muted mt-3 max-w-xl text-[13px] leading-6">Search titles, identifiers, publishers, and subject areas. Open a record to review its metrics and history.</p></div><div className="ji-muted text-[12px]"><span className="ji-heading font-semibold">{journals.length}</span> indexed records</div></div></div>
    <div className="mt-8"><SearchBox initial={query} onSearch={search} /></div>
    <div className="mt-5 flex flex-col gap-3 border-y border-[#dfe5ee] py-3.5 md:flex-row md:items-center md:justify-between"><div className="flex items-center gap-3"><button onClick={() => setFiltersOpen(v => !v)} className="ji-heading flex items-center gap-2 text-[13px] font-semibold md:hidden" data-testid="button-toggle-filters"><SlidersHorizontal size={15} /> Filters</button><span className="ji-muted text-[12px]"><strong className="ji-heading">{visible.length}</strong> journals found</span></div><div className="flex flex-wrap items-center gap-2"><button onClick={() => setSavedOnly(v => !v)} className={`flex items-center gap-2 rounded-sm border px-3 py-2 text-[11px] font-semibold transition ${savedOnly ? 'status-orange border-[#f3c5a8]' : 'border-[#dfe5ee] ji-muted hover:border-[#8faee6]'}`} data-testid="button-filter-saved"><Heart size={13} fill={savedOnly ? 'currentColor' : 'none'} /> Saved only</button><span className="ji-muted hidden text-[11px] sm:block">Sort: <button onClick={() => setSortHigh(v => !v)} className="ji-heading font-semibold" data-testid="button-sort">{sortHigh ? 'SJR highest' : 'Title A–Z'} <ChevronDown size={12} className="inline" /></button></span></div></div>
    <div className="grid gap-7 pt-7 md:grid-cols-[210px_1fr]"><aside className={`${filtersOpen ? 'block' : 'hidden'} space-y-6 md:block`}>
      <FilterGroup label="Subject area"><select value={subject} onChange={e => setSubject(e.target.value)} className="filter-select" data-testid="select-subject">{subjects.map(s => <option key={s}>{s}</option>)}</select></FilterGroup>
      <FilterGroup label="Country / region"><select value={country} onChange={e => setCountry(e.target.value)} className="filter-select" data-testid="select-country">{countries.map(c => <option key={c}>{c}</option>)}</select></FilterGroup>
      <FilterGroup label="Quartile"><div className="flex flex-wrap gap-1.5">{['All quartiles', 'Q1', 'Q2', 'Q3'].map(q => <button key={q} onClick={() => setQuartile(q)} className={`rounded-sm border px-2.5 py-2 text-[11px] ${quartile === q ? 'ji-primary border-[#2557d6]' : 'border-[#dfe5ee] ji-muted hover:border-[#8faee6]'}`} data-testid={`button-quartile-${q.replace(' ', '-').toLowerCase()}`}>{q}</button>)}</div></FilterGroup>
      {(subject !== 'All subjects' || country !== 'All countries' || quartile !== 'All quartiles' || savedOnly) && <button onClick={clearFilters} className="ji-link flex items-center gap-2 text-[11px] font-semibold" data-testid="button-clear-filters"><X size={13} /> Clear all filters</button>}
    </aside><section><div className="grid gap-4 lg:grid-cols-2">{visible.map(journal => <JournalCard key={journal.id} journal={journal} saved={saved.includes(journal.id)} onSave={onSave} />)}</div>{visible.length === 0 && <div className="ji-panel-blue border border-dashed px-6 py-20 text-center"><div className="ji-primary mx-auto grid h-11 w-11 place-items-center rounded-full"><Search size={18} /></div><h2 className="ji-heading mt-5 text-[16px] font-semibold">No journals match this search</h2><p className="ji-muted mx-auto mt-2 max-w-sm text-[13px] leading-6">Try a broader title, a different subject area, or clear the current filters.</p><button onClick={() => { setQuery(''); setLocation('/journals'); clearFilters(); }} className="ji-link mt-5 text-[12px] font-bold" data-testid="button-reset-search">Reset search</button></div>}</section></div>
  </main></Shell>;
}

function FilterGroup({ label, children }: { label: string; children: ReactNode }) { return <div><label className="mono ji-muted mb-2 block text-[10px] uppercase tracking-[.13em]">{label}</label>{children}</div>; }
function Metric({ label, value, note }: { label: string; value: string; note: string }) { return <div className="metric-accent border-l-2 pl-3"><div className="mono ji-muted text-[10px] uppercase tracking-wider">{label}</div><div className="ji-heading mt-2 text-3xl font-semibold tracking-[-.04em]">{value}</div><div className="ji-muted mt-1 text-[11px]">{note}</div></div>; }
function HistoryChart({ history }: { history: Journal['history'] }) {
  const max = Math.max(...history.map(h => h.impact));
  return <div className="mt-6"><div className="flex h-48 items-end gap-3 border-b border-l border-[#d9e2ee] px-2 pt-5 sm:gap-6">{history.map(h => <div key={h.year} className="flex h-full flex-1 flex-col justify-end gap-2"><div className="relative flex flex-1 items-end"><div className="w-full bg-[#5f8de1] transition hover:bg-[#2557d6]" style={{ height: `${(h.impact / max) * 100}%` }}><span className="ji-heading absolute -top-5 left-1/2 -translate-x-1/2 text-[10px] font-semibold">{h.impact}</span></div></div><span className="mono ji-muted text-[10px]">{h.year}</span></div>)}</div><div className="ji-muted mt-4 flex items-center gap-5 text-[11px]"><span className="flex items-center gap-2"><i className="h-2 w-2 bg-[#5f8de1]" /> Impact factor</span><span className="flex items-center gap-2"><span className="h-px w-4 bg-[#e56a2e]" /> SJR tracked annually</span></div></div>;
}

function ManuscriptList({ journal }: { journal: Journal }) {
  const manuscripts = manuscriptsByJournal[journal.id] ?? [
    { title: `${journal.subjects[0]} perspectives in ${journal.title}`, authors: `Editorial record · ${journal.publisher}`, year: '2024', volume: '1', issue: '1', type: 'Research article', citations: 12 },
    { title: `Recent advances in ${journal.subjects.join(' and ').toLowerCase()}`, authors: `Research contributors · ${journal.country}`, year: '2023', volume: '1', issue: '1', type: 'Review article', citations: 9 },
    { title: `Methods and evidence for contemporary ${journal.subjects[0].toLowerCase()} research`, authors: 'Indexed contributors', year: '2023', volume: '1', issue: '1', type: 'Research article', citations: 7 },
  ];

  return <section className="mt-10 border-t border-[#dfe5ee] pt-8"><div className="flex items-end justify-between gap-4"><div><div className="ji-kicker mono text-[10px] uppercase tracking-[.15em]">Indexed publications</div><h2 className="ji-heading mt-2 text-2xl font-semibold">Journal manuscripts</h2></div><span className="ji-muted text-[11px]">{manuscripts.length} records</span></div><div className="ji-card mt-5 divide-y divide-[#dfe5ee]">{manuscripts.map(manuscript => <article key={manuscript.title} className="p-5 transition hover:bg-[#f6f9ff]"><div className="min-w-0"><h3 className="ji-heading text-[15px] font-semibold leading-6">{manuscript.title}</h3><p className="ji-muted mt-2 text-[12px]">{manuscript.authors}</p><div className="ji-muted mt-3 flex flex-wrap items-center gap-x-3 gap-y-1 text-[10px] tracking-[.08em]"><span>{manuscript.type}</span><span aria-hidden="true">|</span><span>Vol {manuscript.volume}, Issue {manuscript.issue} {manuscript.year}</span><span aria-hidden="true">|</span><span>{manuscript.citations} Citations.</span></div></div></article>)}</div></section>;
}

function Profile({ saved, onSave }: { saved: string[]; onSave: (id: string) => void }) {
  const { id } = useParams<{ id: string }>();
  const journal = journals.find(item => item.id === id);
  if (!journal) return <Shell savedCount={saved.length}><div className="mx-auto max-w-xl px-5 py-32 text-center"><div className="ji-kicker mono text-xs">404 / RECORD NOT FOUND</div><h1 className="ji-heading mt-4 text-4xl font-semibold">That journal is not in the index.</h1><Link href="/journals" className="ji-link mt-8 inline-flex items-center gap-2 text-sm font-semibold" data-testid="link-back-directory">Back to directory <ArrowRight size={16} /></Link></div></Shell>;
  return <Shell savedCount={saved.length}><main className="mx-auto max-w-[1240px] px-5 pb-20 pt-10 lg:px-8 lg:pt-12">
    <div className="ji-muted flex items-center gap-2 text-[11px]"><Link href="/journals" className="ji-link hover:underline" data-testid="link-profile-directory">Directory</Link><ChevronRight size={13} /><span>{journal.abbreviation}</span></div>
    <section className="mt-6 border-b border-[#dfe5ee] pb-8"><div className="flex flex-col gap-7 md:flex-row md:items-start md:justify-between"><div className="max-w-3xl"><h1 className="ji-heading text-4xl font-semibold leading-tight tracking-[-.04em] sm:text-5xl">{journal.title}</h1><div className="mt-3 flex flex-wrap items-center gap-2 text-[13px]"><Pill tone="blue">Indexed record</Pill><Pill>{journal.quartile} · 2024</Pill>{journal.openAccess && <Pill tone="green">Open access</Pill>}</div><p className="ji-muted mt-5 max-w-2xl text-[14px] leading-6">{journal.description}</p></div><button onClick={() => onSave(journal.id)} className={`flex w-fit items-center gap-2 rounded-sm border px-4 py-2.5 text-[12px] font-semibold transition ${saved.includes(journal.id) ? 'status-orange border-[#f3c5a8]' : 'ji-outline border hover:bg-[#edf3ff]'}`} data-testid="button-profile-save"><Heart size={15} fill={saved.includes(journal.id) ? 'currentColor' : 'none'} /> {saved.includes(journal.id) ? 'Saved to shortlist' : 'Save journal'}</button></div><div className="mt-7 border-t border-[#dfe5ee] pt-6"><div className="ji-heading flex items-center gap-2 text-[13px] font-semibold"><Award size={16} className="ji-orange" /> Subject coverage</div><div className="mt-3 flex flex-wrap gap-2">{journal.subjects.map(s => <Pill key={s} tone="blue">{s}</Pill>)}</div></div><div className="ji-panel-blue mt-7 border p-5"><div className="ji-heading flex items-center gap-2 text-[12px] font-bold uppercase tracking-[.1em]"><Info size={15} className="ji-orange" /> Summary journal</div><div className="mt-5 grid gap-5 border-t border-[#cddcf4] pt-5 sm:grid-cols-2"><div><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Publisher</div><Link href={`/publisher/${publisherSlug(journal.publisher)}`} className="ji-link mt-2 block text-[13px] font-semibold hover:underline" data-testid="link-profile-publisher">{journal.publisher}</Link></div><div><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Country</div><div className="ji-heading mt-2 text-[13px] font-semibold">{journal.country}</div></div><div><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">ISSN</div><div className="ji-heading mt-2 text-[13px] font-semibold">{journal.issn || '-'}</div></div><div><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">E-ISSN</div><div className="ji-heading mt-2 text-[13px] font-semibold">{journal.eIssn || '-'}</div></div><div><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Founded</div><div className="ji-heading mt-2 text-[13px] font-semibold">{journal.founded}</div></div><div><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Frequency</div><div className="ji-heading mt-2 text-[13px] font-semibold">{journal.frequency}</div></div><div className="sm:col-span-2"><div className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Subject</div><div className="ji-heading mt-2 text-[13px] font-semibold">{journal.subjects.join(' · ')}</div></div></div></div></section>
    <section className="py-9"><div><div className="grid grid-cols-2 gap-x-8 gap-y-8 border-b border-[#dfe5ee] pb-9 sm:grid-cols-4"><Metric label="SJR" value={journal.sjr} note="SCImago Journal Rank" /><Metric label="Impact factor" value={journal.impact} note="2024 edition" /><Metric label="H-index" value={String(journal.hIndex)} note="Citedness over time" /><Metric label="CiteScore" value={journal.citeScore} note="Scopus 2024" /></div><div className="pt-9"><div className="flex items-end justify-between"><div><div className="ji-kicker mono text-[10px] uppercase tracking-[.15em]">Five-year view</div><h2 className="ji-heading mt-2 text-2xl font-semibold">Metric history</h2></div><span className="ji-muted text-[11px]">2020 — 2024</span></div><HistoryChart history={journal.history} /></div><ManuscriptList journal={journal} /></div></section>
  </main></Shell>;
}

function PublisherProfile({ savedCount }: { savedCount: number }) {
  const { slug } = useParams<{ slug: string }>();
  const publisherJournals = journals.filter(journal => publisherSlug(journal.publisher) === slug);
  if (!publisherJournals.length) return <Shell savedCount={savedCount}><div className="mx-auto max-w-xl px-5 py-32 text-center"><div className="ji-kicker mono text-xs">404 / PUBLISHER NOT FOUND</div><h1 className="ji-heading mt-4 text-4xl font-semibold">That publisher is not in the index.</h1><Link href="/journals" className="ji-link mt-8 inline-flex items-center gap-2 text-sm font-semibold" data-testid="link-publisher-404-directory">Back to directory <ArrowRight size={16} /></Link></div></Shell>;

  const publisher = publisherJournals[0].publisher;
  const origins = [...new Set(publisherJournals.map(journal => journal.country))];
  const subjectAreas = [...new Set(publisherJournals.flatMap(journal => journal.subjects))];
  const description = publisherDescriptions[publisher] ?? `${publisher} is an academic publishing organization represented in the index through peer-reviewed journals and research across ${subjectAreas.slice(0, 2).join(' and ').toLowerCase()}.`;

  return <Shell savedCount={savedCount}><main className="mx-auto max-w-[1240px] px-5 pb-20 pt-10 lg:px-8 lg:pt-12">
    <div className="ji-muted flex items-center gap-2 text-[11px]"><Link href="/journals" className="ji-link hover:underline" data-testid="link-publisher-directory">Directory</Link><ChevronRight size={13} /><span>Publisher</span><ChevronRight size={13} /><span>{publisher}</span></div>
    <section className="mt-6 border-b border-[#dfe5ee] pb-9"><div className="ji-kicker mono text-[10px] uppercase tracking-[.18em]">Publisher profile</div><h1 className="ji-heading mt-3 max-w-3xl text-4xl font-semibold tracking-[-.04em] sm:text-5xl">{publisher}</h1><p className="ji-muted mt-5 max-w-2xl text-[14px] leading-7">{description}</p><div className="ji-muted mt-6 flex flex-wrap gap-x-6 gap-y-2 text-[11px]"><span className="flex items-center gap-2"><Globe2 size={14} className="ji-link" /> Journal origin · {origins.join(' · ')}</span><span className="flex items-center gap-2"><Library size={14} className="ji-link" /> {publisherJournals.length} indexed {publisherJournals.length === 1 ? 'journal' : 'journals'}</span></div></section>
    <div className="grid gap-9 pt-9 lg:grid-cols-[1fr_310px]"><section><div className="flex items-end justify-between gap-4"><div><div className="ji-kicker mono text-[10px] uppercase tracking-[.15em]">Publisher catalogue</div><h2 className="ji-heading mt-2 text-2xl font-semibold">Journals from this publisher</h2></div><span className="ji-muted text-[11px]">{publisherJournals.length} records</span></div><div className="ji-card mt-5 divide-y divide-[#dfe5ee] border">{publisherJournals.map(journal => <article key={journal.id} className="p-5 transition hover:bg-[#f6f9ff]"><Link href={`/journals/${journal.id}`} className="block" data-testid={`link-publisher-journal-${journal.id}`}><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><div className="mono ji-orange text-[10px] uppercase tracking-wider">{journal.abbreviation} · ISSN {journal.issn}</div><h3 className="ji-heading mt-2 text-[16px] font-semibold leading-6">{journal.title}</h3></div><Pill tone={journal.quartile === 'Q1' ? 'blue' : 'neutral'}>{journal.quartile}</Pill></div><p className="ji-muted mt-3 max-w-2xl text-[13px] leading-5">{journal.description}</p><div className="mt-4 flex flex-wrap gap-1.5">{journal.subjects.map(subject => <Pill key={subject}>{subject}</Pill>)}<Pill tone="green">{journal.country}</Pill></div></Link></article>)}</div></section><aside className="ji-panel-blue h-fit border p-5"><div className="ji-heading flex items-center gap-2 text-[13px] font-semibold"><Building2 size={16} className="ji-link" /> Publisher details</div><dl className="mt-5 space-y-5 border-t border-[#cddcf4] pt-5"><div><dt className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Name</dt><dd className="ji-heading mt-2 text-[13px] font-semibold">{publisher}</dd></div><div><dt className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Journal origin</dt><dd className="ji-heading mt-2 text-[13px] font-semibold">{origins.join(' · ')}</dd></div><div><dt className="mono ji-muted text-[10px] uppercase tracking-[.13em]">Subject coverage</dt><dd className="ji-heading mt-2 text-[13px] font-semibold">{subjectAreas.join(' · ')}</dd></div></dl></aside></div>
  </main></Shell>;
}

function PublisherLanding({ savedCount }: { savedCount: number }) {
  return <Shell savedCount={savedCount}><main><section className="ji-heading bg-[#263e64] text-white"><div className="mx-auto grid max-w-[1240px] gap-12 px-5 py-16 lg:grid-cols-[1fr_.75fr] lg:items-center lg:px-8 lg:py-20"><div><div className="ji-orange mono text-[10px] uppercase tracking-[.18em]">For publishers and editorial teams</div><h1 className="mt-4 max-w-2xl text-4xl font-semibold leading-tight tracking-[-.04em] sm:text-5xl">Make your journal easier to find and evaluate.</h1><p className="mt-5 max-w-lg text-[14px] leading-7 text-[#d3ddec]">Submit a title for consideration, keep its metadata current, and help researchers understand the work your journal carries.</p><div className="mt-7 flex flex-wrap gap-3"><Link href="/publisher/submit" className="flex items-center gap-2 rounded-sm bg-[#e56a2e] px-4 py-3 text-[13px] font-semibold text-white hover:bg-[#c9541c]" data-testid="link-publisher-submit">Suggest a journal <ArrowRight size={15} /></Link><Link href="/publisher/dashboard" className="rounded-sm border border-[#90a7ce] px-4 py-3 text-[13px] font-semibold text-white hover:border-white" data-testid="link-publisher-dashboard-hero">Open publisher dashboard</Link></div></div><div className="border border-[#7185a9] p-3"><div className="border border-[#7185a9] p-5"><div className="flex justify-between"><span className="mono ji-orange text-[10px]">SUBMISSION PATH</span><span className="text-[11px] text-[#b9c7dc]">01 — 03</span></div><div className="mt-8 space-y-4">{([['01', 'Tell us about the journal', true], ['02', 'Editorial review', false], ['03', 'Listed for discovery', false]] as const).map(([n, t, active]) => <div key={n} className={`flex items-center gap-3 border-b border-[#7185a9] pb-3 ${active ? 'text-white' : 'text-[#b9c7dc]'}`}><span className={`grid h-7 w-7 place-items-center rounded-full text-[11px] ${active ? 'bg-[#e56a2e]' : 'border border-[#7185a9]'}`}>{active ? <Check size={13} /> : n}</span><span className="text-[13px]">{t}</span></div>)}</div><p className="mt-5 text-[11px] leading-5 text-[#b9c7dc]">Have your ISSN, publisher details, and subject scope ready.</p></div></div></div></section><section className="mx-auto max-w-[1240px] px-5 py-14 lg:px-8 lg:py-20"><div className="grid gap-8 md:grid-cols-3">{[['Metadata that travels', 'Share a consistent, human-readable record across discovery conversations.'], ['A review with context', 'Our editorial team checks scope, identity, and the evidence behind a submission.'], ['A public record', 'Once indexed, your journal is visible in the public directory.']].map(([t, d], i) => <div key={t} className="border-t-2 border-[#2557d6] pt-4"><span className="ji-orange mono text-[11px]">0{i + 1}</span><h2 className="ji-heading mt-6 text-[15px] font-semibold">{t}</h2><p className="ji-muted mt-2 text-[13px] leading-6">{d}</p></div>)}</div></section></main></Shell>;
}

const submissions = [{ title: 'Journal of Applied Coastal Studies', id: 'SUB-24018', status: 'Under editorial review', date: '18 Mar 2024', tone: 'review' }, { title: 'Nusantara Health Policy Review', id: 'SUB-23971', status: 'More information needed', date: '02 Mar 2024', tone: 'action' }, { title: 'Indonesian Journal of Information Systems', id: 'IDX-00419', status: 'Indexed', date: '12 Jan 2024', tone: 'indexed' }];

function PublisherDashboard({ savedCount }: { savedCount: number }) {
  return <Shell savedCount={savedCount}><main className="mx-auto max-w-[1240px] px-5 pb-20 pt-10 lg:px-8 lg:pt-12"><div className="flex flex-col justify-between gap-5 border-b border-[#dfe5ee] pb-7 md:flex-row md:items-end"><div><div className="ji-kicker mono text-[10px] uppercase tracking-[.18em]">Publisher workspace</div><h1 className="ji-heading mt-3 text-4xl font-semibold tracking-[-.04em]">Editorial workspace</h1><p className="ji-muted mt-2 text-[13px]">Mosaic Research Group · <span className="mono text-[10px]">PUB-00382</span></p></div><Link href="/publisher/submit" className="ji-primary flex w-fit items-center gap-2 rounded-sm px-4 py-2.5 text-[12px] font-semibold" data-testid="link-dashboard-new-submission">New submission <ArrowRight size={14} /></Link></div><div className="grid gap-4 py-7 sm:grid-cols-3">{[['02', 'Active submissions', 'Across 2 titles'], ['01', 'Indexed journals', 'Visible in directory'], ['01', 'Action required', 'Needs your reply']].map(([n, l, d], i) => <div key={l} className={`ji-card border p-5 ${i === 2 ? 'status-orange border-[#f3c5a8]' : ''}`}><div className="ji-heading mono text-3xl">{n}</div><div className="ji-heading mt-4 text-[13px] font-semibold">{l}</div><div className="ji-muted mt-1 text-[11px]">{d}</div></div>)}</div><div className="grid gap-9 lg:grid-cols-[1fr_330px]"><section><h2 className="ji-heading text-[16px] font-semibold">Submission activity</h2><div className="ji-card mt-3 overflow-hidden border">{submissions.map(sub => <div key={sub.id} className="flex flex-col gap-3 border-b border-[#e7edf5] p-4 last:border-b-0 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><div className={`mt-1 grid h-7 w-7 shrink-0 place-items-center rounded-full ${sub.tone === 'indexed' ? 'status-green' : sub.tone === 'action' ? 'status-orange' : 'status-neutral'}`}>{sub.tone === 'indexed' ? <Check size={14} /> : sub.tone === 'action' ? <Info size={14} /> : <Clock3 size={14} />}</div><div><div className="ji-heading text-[13px] font-semibold">{sub.title}</div><div className="mono ji-muted mt-1 text-[9px] uppercase tracking-wider">{sub.id} · Submitted {sub.date}</div></div></div><Pill tone={sub.tone === 'indexed' ? 'green' : sub.tone === 'action' ? 'orange' : 'neutral'}>{sub.status}</Pill></div>)}</div></section><aside><h2 className="ji-heading text-[16px] font-semibold">Your journals</h2><div className="ji-card mt-3 border p-4"><div className="flex items-start justify-between gap-3"><div><div className="ji-heading text-[13px] font-semibold">Indonesian Journal of Information Systems</div><div className="mono ji-muted mt-2 text-[9px]">ISSN 2548-6550</div></div><Pill tone="green">Indexed</Pill></div><Link href="/journals/ijis" className="ji-link mt-5 flex items-center gap-1 text-[11px] font-bold" data-testid="link-owned-journal">View public record <ArrowRight size={14} /></Link></div><div className="ji-panel-blue mt-3 border p-4"><div className="flex gap-3"><Building2 size={17} className="ji-link" /><div><div className="ji-heading text-[13px] font-semibold">Have another title?</div><p className="ji-muted mt-1.5 text-[11px] leading-5">Add a journal to your publisher workspace.</p><Link href="/publisher/submit" className="ji-link mt-2 inline-block text-[11px] font-bold" data-testid="link-add-journal">Suggest a journal <ArrowRight size={12} className="inline" /></Link></div></div></div></aside></div></main></Shell>;
}

function SubmitForm({ savedCount }: { savedCount: number }) {
  const [submitted, setSubmitted] = useState(false);
  const [form, setForm] = useState({ title: '', issn: '', publisher: '', country: 'Indonesia', website: '', subjects: '', notes: '' });
  const [error, setError] = useState('');
  const update = (key: keyof typeof form) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => setForm(v => ({ ...v, [key]: e.target.value }));
  const submit = (e: FormEvent) => { e.preventDefault(); if (!form.title || !form.issn || !form.publisher || !form.subjects) { setError('Please complete the required fields before sending your suggestion.'); return; } setError(''); setSubmitted(true); };
  if (submitted) return <Shell savedCount={savedCount}><main className="mx-auto max-w-[760px] px-5 py-20"><div className="ji-panel-blue border p-8 text-center sm:p-14"><div className="ji-primary mx-auto grid h-12 w-12 place-items-center rounded-full"><Check size={23} /></div><div className="ji-kicker mono mt-6 text-[10px] uppercase tracking-[.18em]">Submission received · JIP-24031</div><h1 className="ji-heading mt-3 text-4xl font-semibold tracking-[-.04em]">Thank you for adding to the record.</h1><p className="ji-muted mx-auto mt-5 max-w-md text-[13px] leading-6">Our editorial team will review the journal identity, scope, and metadata. You can expect an update within 10 working days.</p><div className="mt-7 flex flex-wrap justify-center gap-3"><Link href="/publisher/dashboard" className="ji-primary rounded-sm px-4 py-3 text-[12px] font-semibold" data-testid="link-success-dashboard">Go to dashboard</Link><Link href="/journals" className="ji-link rounded-sm border border-[#bcd0ee] px-4 py-3 text-[12px] font-semibold" data-testid="link-success-directory">Explore directory</Link></div></div></main></Shell>;
  return <Shell savedCount={savedCount}><main className="mx-auto max-w-[1000px] px-5 pb-20 pt-10 lg:px-8 lg:pt-12"><div className="border-b border-[#dfe5ee] pb-7"><div className="ji-kicker mono text-[10px] uppercase tracking-[.18em]">Publisher workspace · New suggestion</div><h1 className="ji-heading mt-3 text-4xl font-semibold tracking-[-.04em] sm:text-5xl">Suggest a journal for indexing.</h1><p className="ji-muted mt-4 max-w-lg text-[13px] leading-6">Give researchers a reliable starting record. We ask for the core metadata first; our team will follow up if we need more context.</p></div><form onSubmit={submit} className="mt-8 grid gap-9 lg:grid-cols-[1fr_280px]"><div className="space-y-6"><Field label="Journal title" required><input value={form.title} onChange={update('title')} placeholder="e.g. Journal of Applied Coastal Studies" className="form-input" data-testid="input-submit-title" /></Field><div className="grid gap-6 sm:grid-cols-2"><Field label="ISSN (print or online)" required><input value={form.issn} onChange={update('issn')} placeholder="e.g. 2754-1182" className="form-input" data-testid="input-submit-issn" /></Field><Field label="Publisher / institution" required><input value={form.publisher} onChange={update('publisher')} placeholder="Publishing organization" className="form-input" data-testid="input-submit-publisher" /></Field></div><div className="grid gap-6 sm:grid-cols-2"><Field label="Country / region"><select value={form.country} onChange={update('country')} className="form-input" data-testid="select-submit-country">{countries.slice(1).map(c => <option key={c}>{c}</option>)}</select></Field><Field label="Journal website"><input value={form.website} onChange={update('website')} placeholder="https://" className="form-input" data-testid="input-submit-website" /></Field></div><Field label="Primary subject areas" required><input value={form.subjects} onChange={update('subjects')} placeholder="e.g. Marine science, public policy" className="form-input" data-testid="input-submit-subjects" /></Field><Field label="A note for the editorial team"><textarea value={form.notes} onChange={update('notes')} placeholder="Tell us anything useful about the journal's scope or history." rows={5} className="form-input resize-none" data-testid="textarea-submit-notes" /></Field>{error && <div className="status-orange flex items-center gap-2 border border-[#f3c5a8] px-4 py-3 text-[13px]" role="alert" data-testid="status-submit-error"><Info size={16} /> {error}</div>}<button type="submit" className="ji-primary flex w-full items-center justify-center gap-2 rounded-sm px-5 py-3.5 text-[13px] font-semibold transition hover:bg-[#173aa0]" data-testid="button-submit-journal">Send for consideration <Send size={16} /></button></div><aside className="ji-panel-blue h-fit border p-5"><div className="ji-heading flex items-center gap-2 text-[13px] font-semibold"><ShieldCheck size={16} className="ji-link" /> What happens next</div><ol className="mt-5 space-y-5">{[['01', 'We check the record', 'Title, ISSN, publisher identity, and public scope.'], ['02', 'We ask when needed', 'A member of the team will contact your editorial office.'], ['03', 'We publish the context', 'Approved titles appear in the public directory.']].map(([n, t, d]) => <li key={n} className="flex gap-3"><span className="ji-orange mono text-[10px]">{n}</span><div><div className="ji-heading text-[12px] font-bold">{t}</div><p className="ji-muted mt-1 text-[11px] leading-5">{d}</p></div></li>)}</ol></aside></form></main></Shell>;
}

function Field({ label, required, children }: { label: string; required?: boolean; children: ReactNode }) { return <label className="block"><span className="ji-heading mb-2 block text-[12px] font-semibold">{label} {required && <span className="ji-orange">*</span>}</span>{children}</label>; }

function Router({ saved, onSave }: { saved: string[]; onSave: (id: string) => void }) {
  return <Switch>
    <Route path="/" component={() => <Home savedCount={saved.length} />} />
    <Route path="/journals" component={() => <Directory saved={saved} onSave={onSave} />} />
    <Route path="/journals/:id" component={() => <Profile saved={saved} onSave={onSave} />} />
    <Route path="/publisher" component={() => <PublisherLanding savedCount={saved.length} />} />
    <Route path="/publisher/dashboard" component={() => <PublisherDashboard savedCount={saved.length} />} />
    <Route path="/publisher/submit" component={() => <SubmitForm savedCount={saved.length} />} />
    <Route path="/publisher/:slug" component={() => <PublisherProfile savedCount={saved.length} />} />
    <Route component={() => <Shell savedCount={saved.length}><div className="mx-auto max-w-xl px-5 py-32 text-center"><div className="ji-kicker mono text-xs">404 / PAGE NOT FOUND</div><h1 className="ji-heading mt-4 text-4xl font-semibold">This page is outside the index.</h1><Link href="/" className="ji-link mt-8 inline-flex items-center gap-2 text-sm font-semibold" data-testid="link-404-home">Return home <ArrowRight size={16} /></Link></div></Shell>} />
  </Switch>;
}

function App() {
  const [saved, setSaved] = useState<string[]>([]);
  const onSave = (id: string) => setSaved(items => items.includes(id) ? items.filter(item => item !== id) : [...items, id]);
  return <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router saved={saved} onSave={onSave} /></WouterRouter>;
}

export default App;